import Foundation

// MARK: - Content models (ExamContent.json, generated by tools/build_content.py)

struct DialogueLine: Codable, Hashable {
    let speaker: String   // "M" man, "F" woman, "N" narrator
    let text: String
    let pinyin: String

    var label: String {
        switch speaker {
        case "M": "男："
        case "F": "女："
        default: ""
        }
    }
}

struct ListeningItem: Codable, Identifiable {
    let id: String
    let level: Int
    let kind: String              // picture | statement | dialogue | passage
    let lines: [DialogueLine]
    let english: String
    let picture: String?
    let statement: String?
    let statementPinyin: String?
    let statementEnglish: String?
    let isTrue: Bool?
    let question: String?
    let questionPinyin: String?
    let questionEnglish: String?
    let options: [String]?
    let answer: Int?
}

struct ReadingItem: Codable, Identifiable {
    let id: String
    let level: Int
    let kind: String              // reply | cloze | passageTrueFalse | passageQuestion
    let text: String
    let pinyin: String
    let english: String?
    let reply: String?
    let replyPinyin: String?
    let statement: String?
    let statementPinyin: String?
    let statementEnglish: String?
    let isTrue: Bool?
    let question: String?
    let questionPinyin: String?
    let questionEnglish: String?
    let options: [String]?
    let answer: Int?
}

private struct ContentFile: Codable {
    let listening: [ListeningItem]
    let reading: [ReadingItem]
}

enum ContentStore {
    private static let file: ContentFile = {
        guard let url = Bundle.main.url(forResource: "ExamContent", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let decoded = try? JSONDecoder().decode(ContentFile.self, from: data) else {
            assertionFailure("ExamContent.json missing or malformed")
            return ContentFile(listening: [], reading: [])
        }
        return decoded
    }()

    /// Items for a level; if there are fewer than `atLeast`, lower levels are added too.
    static func listening(level: Int, kinds: Set<String>, atLeast: Int = 0, where extra: (ListeningItem) -> Bool = { _ in true }) -> [ListeningItem] {
        widen(level: level, atLeast: atLeast) { lvl in
            file.listening.filter { $0.level == lvl && kinds.contains($0.kind) && extra($0) }
        }
    }

    static func reading(level: Int, kinds: Set<String>, atLeast: Int = 0) -> [ReadingItem] {
        widen(level: level, atLeast: atLeast) { lvl in
            file.reading.filter { $0.level == lvl && kinds.contains($0.kind) }
        }
    }

    private static func widen<T>(level: Int, atLeast: Int, _ fetch: (Int) -> [T]) -> [T] {
        var out = fetch(level)
        var lvl = level - 1
        while out.count < atLeast && lvl >= 1 {
            out += fetch(lvl)
            lvl -= 1
        }
        return out
    }
}

// MARK: - Question model shared by the exam and exam-style practice

enum ExamSection: String, CaseIterable {
    case listening = "Listening 听力"
    case reading = "Reading 阅读"
    var skill: Skill { self == .listening ? .listening : .reading }
}

struct AnswerOption: Hashable {
    var text: String = ""
    var picture: String? = nil
}

struct ExamQuestion: Identifiable {
    let id = UUID()
    let section: ExamSection
    let part: String                  // e.g. "第一部分 · Picture true or false"
    let instruction: String
    var audio: [DialogueLine]? = nil  // played, never shown during the question
    var audioQuestion: String? = nil  // read aloud after the recording ("问：…")
    var picture: String? = nil        // big picture shown with the question
    var text: String? = nil           // sentence / passage / question shown
    var statement: String? = nil      // ★ statement to judge
    let options: [AnswerOption]
    let answer: Int
    let itemID: String
    // Shown after answering:
    var transcript: [DialogueLine] = []
    var english: String = ""
    var note: String = ""

    var usesPictures: Bool { options.allSatisfy { $0.picture != nil } }
    static let trueFalse = [AnswerOption(text: "✓  对 (true)"), AnswerOption(text: "✗  错 (false)")]
}

// MARK: - Builder (structure modelled on the HSK 2.0 papers; questions are original)

enum ExamBuilder {
    static let perPart = 5

    static func timeLimit(level: Int) -> Int {
        [1: 35, 2: 45, 3: 60][level, default: 45] * 60
    }

    /// A full practice exam: 4 listening parts + 4 reading parts, 5 questions each.
    static func exam(level: Int) -> [ExamQuestion] {
        usedPictures = []
        let n = perPart
        let parts: [[ExamQuestion]]
        switch level {
        case 1:
            parts = [listenWordPictureTF(level, n), listenPictureChoice(level, n, multiLine: false),
                     listenPictureChoice(level, n, multiLine: true), listenDialogue(level, n, kinds: ["dialogue"]),
                     readWordPictureTF(level, n), readSentencePicture(level, n),
                     readReply(level, n), readCloze(level, n)]
        case 2:
            parts = [listenPictureTF(level, n), listenPictureChoice(level, n, multiLine: true),
                     listenDialogue(level, n, kinds: ["dialogue"]), listenStatementTF(level, n),
                     readSentencePicture(level, n), readCloze(level, n),
                     readPassageTF(level, n), readReply(level, n)]
        default:
            parts = [listenPictureChoice(level, n, multiLine: true), listenStatementTF(level, n),
                     listenDialogue(level, n, kinds: ["dialogue"]), listenDialogue(level, n, kinds: ["passage"]),
                     readReply(level, n), readCloze(level, n),
                     readPassageTF(level, n), readPassageQuestion(level, n)]
        }
        return parts.flatMap { $0 }
    }

    /// Exam-style practice for one section: a mix of that section's question types.
    static func practice(section: ExamSection, level: Int, count: Int = 10) -> [ExamQuestion] {
        usedPictures = []
        let parts: [[ExamQuestion]]
        switch section {
        case .listening:
            parts = [listenWordPictureTF(level, 2), listenPictureChoice(level, 2, multiLine: nil),
                     listenStatementTF(level, 2), listenDialogue(level, 3, kinds: ["dialogue"]),
                     level >= 3 ? listenDialogue(level, 2, kinds: ["passage"]) : listenPictureTF(level, 2)]
        case .reading:
            parts = [readWordPictureTF(level, 2), readSentencePicture(level, 2), readReply(level, 2),
                     readCloze(level, 3), level >= 2 ? readPassageTF(level, 2) : readCloze(level, 1),
                     level >= 3 ? readPassageQuestion(level, 2) : []]
        }
        return Array(parts.flatMap { $0 }.prefix(count))
    }

    // MARK: Helpers

    private static func narrator(_ text: String, _ pinyin: String) -> DialogueLine {
        DialogueLine(speaker: "N", text: text, pinyin: pinyin)
    }

    // MARK: No repeated pictures

    /// Photos already shown as the main picture in the exam being built.
    private static var usedPictures: Set<String> = []

    /// What is actually shown: emojis that share a photo count as the same picture.
    static func identity(_ picture: String?) -> String {
        guard let picture else { return "" }
        return PhotoStore.shared.titles[picture] ?? picture
    }

    /// Picks n items whose pictures haven't been shown yet in this exam (and differ from each other).
    private static func fresh<T>(_ items: [T], _ n: Int, picture: (T) -> String?) -> [T] {
        var out: [T] = []
        for item in items where out.count < n {
            let id = identity(picture(item))
            if id.isEmpty || !usedPictures.contains(id) {
                out.append(item)
                if !id.isEmpty { usedPictures.insert(id) }
            }
        }
        return out
    }

    /// A random different picture (for "doesn't match" questions), also not shown before.
    private static func freshOtherPicture(than correct: String, level: Int) -> String? {
        let candidates = otherPictures(excluding: correct, level: level, count: 30)
        let pick = candidates.first { !usedPictures.contains(identity($0)) } ?? candidates.first
        if let pick { usedPictures.insert(identity(pick)) }
        return pick
    }

    private static func samePicture(_ a: Word, _ b: Word) -> Bool {
        let id = { (w: Word) in w.emoji.map { PhotoStore.shared.titles[$0] ?? $0 } ?? w.id }
        return id(a) == id(b)
    }

    private static func pictureWords(_ level: Int) -> [Word] {
        var words = VocabularyStore.all.filter { $0.level == level && $0.emoji != nil }
        if words.count < 8 { words += VocabularyStore.all.filter { $0.level < level && $0.emoji != nil } }
        return words
    }

    /// Other pictures to use as wrong options.
    private static func otherPictures(excluding emoji: String, level: Int, count: Int) -> [String] {
        let scenes = ContentStore.listening(level: level, kinds: ["picture"], atLeast: 10).compactMap(\.picture)
        let words = pictureWords(level).compactMap(\.emoji)
        // Two pictures can share a photo (e.g. 🎂 and 🍰) — compare by what is actually shown.
        var seen: Set<String> = [identity(emoji)]
        var out: [String] = []
        for e in (scenes.shuffled() + words.shuffled()) where !seen.contains(identity(e)) {
            seen.insert(identity(e)); out.append(e)
            if out.count == count { break }
        }
        return out
    }

    private static func pictureOptions(correct: String, level: Int, total: Int) -> ([AnswerOption], Int) {
        var pics = [correct] + otherPictures(excluding: correct, level: level, count: total - 1)
        pics.shuffle()
        return (pics.map { AnswerOption(picture: $0) }, pics.firstIndex(of: correct) ?? 0)
    }

    private static func textOptions(correct: String, wrong: [String]) -> ([AnswerOption], Int) {
        var unique: [String] = []
        for w in wrong where w != correct && !unique.contains(w) { unique.append(w) }
        let shown = ([correct] + unique.shuffled().prefix(3)).shuffled()
        return (shown.map { AnswerOption(text: $0) }, shown.firstIndex(of: correct) ?? 0)
    }

    // MARK: Listening parts

    /// Hear a word; does it match the picture?
    static func listenWordPictureTF(_ level: Int, _ n: Int) -> [ExamQuestion] {
        let words = pictureWords(level).shuffled()
        return fresh(words, n, picture: \.emoji).map { w in
            let match = Bool.random()
            let other = words.shuffled().first {
                $0.id != w.id && !samePicture($0, w) && !usedPictures.contains(identity($0.emoji))
            }
            if let other, !match { usedPictures.insert(identity(other.emoji)) }
            let shownWord = match ? w : (other ?? w)
            return ExamQuestion(
                section: .listening, part: "Picture: true or false", instruction: "Listen. Does the word match the picture?",
                audio: [narrator(w.hanzi, w.pinyin)], picture: shownWord.emoji,
                options: ExamQuestion.trueFalse, answer: shownWord.id == w.id ? 0 : 1, itemID: w.id,
                transcript: [narrator(w.hanzi, w.pinyin)], english: "\(w.hanzi) means “\(w.english)”.",
                note: shownWord.id == w.id ? "The picture shows \(w.hanzi)." : "The picture shows \(shownWord.hanzi) (\(shownWord.english)).")
        }
    }

    /// Hear a sentence or dialogue; is the picture right?
    static func listenPictureTF(_ level: Int, _ n: Int) -> [ExamQuestion] {
        let items = ContentStore.listening(level: level, kinds: ["picture"], atLeast: n).shuffled()
        return fresh(items, n, picture: \.picture).compactMap { item in
            guard let correct = item.picture else { return nil }
            let match = Bool.random()
            let shown = match ? correct : (freshOtherPicture(than: correct, level: level) ?? correct)
            return ExamQuestion(
                section: .listening, part: "Picture: true or false", instruction: "Listen. Does the recording match the picture?",
                audio: item.lines, picture: shown, options: ExamQuestion.trueFalse, answer: shown == correct ? 0 : 1,
                itemID: item.id, transcript: item.lines, english: item.english,
                note: "The matching picture is \(correct).")
        }
    }

    /// Hear a sentence/dialogue; choose the picture. multiLine: true = dialogues, false = single sentences, nil = any.
    static func listenPictureChoice(_ level: Int, _ n: Int, multiLine: Bool?) -> [ExamQuestion] {
        let items = ContentStore.listening(level: level, kinds: ["picture"], atLeast: n) {
            multiLine == nil || ($0.lines.count > 1) == multiLine!
        }.shuffled()
        let fallback = items.count < n ? ContentStore.listening(level: level, kinds: ["picture"], atLeast: n).shuffled() : []
        return fresh(items + fallback.filter { f in !items.contains { $0.id == f.id } }, n, picture: \.picture).compactMap { item in
            guard let correct = item.picture else { return nil }
            let (opts, ans) = pictureOptions(correct: correct, level: level, total: level == 1 ? 3 : 4)
            return ExamQuestion(
                section: .listening, part: "Choose the picture",
                instruction: item.lines.count > 1 ? "Listen to the dialogue and choose the matching picture." : "Listen and choose the matching picture.",
                audio: item.lines, options: opts, answer: ans, itemID: item.id,
                transcript: item.lines, english: item.english)
        }
    }

    /// Hear a dialogue or passage, then a question; choose the answer.
    static func listenDialogue(_ level: Int, _ n: Int, kinds: Set<String>) -> [ExamQuestion] {
        let items = ContentStore.listening(level: level, kinds: kinds, atLeast: n).shuffled()
        return items.prefix(n).compactMap { item in
            guard let q = item.question, let options = item.options, let answer = item.answer else { return nil }
            let isPassage = item.kind == "passage"
            return ExamQuestion(
                section: .listening, part: isPassage ? "Listen to the passage" : "Dialogue and question",
                instruction: "Listen, then answer the question you hear.",
                audio: item.lines, audioQuestion: q,
                options: options.map { AnswerOption(text: $0) }, answer: answer, itemID: item.id,
                transcript: item.lines + [narrator("问：" + q, item.questionPinyin ?? "")],
                english: item.english + "\nQ: " + (item.questionEnglish ?? ""))
        }
    }

    /// Hear a passage; is the ★ statement true?
    static func listenStatementTF(_ level: Int, _ n: Int) -> [ExamQuestion] {
        let items = ContentStore.listening(level: level, kinds: ["statement"], atLeast: n).shuffled()
        return items.prefix(n).compactMap { item in
            guard let star = item.statement, let isTrue = item.isTrue else { return nil }
            return ExamQuestion(
                section: .listening, part: "True or false ★", instruction: "Listen, then decide if the ★ sentence is true.",
                audio: item.lines, statement: star, options: ExamQuestion.trueFalse, answer: isTrue ? 0 : 1,
                itemID: item.id, transcript: item.lines,
                english: item.english + "\n★ " + (item.statementEnglish ?? ""))
        }
    }

    // MARK: Reading parts

    /// See a word and a picture; do they match?
    static func readWordPictureTF(_ level: Int, _ n: Int) -> [ExamQuestion] {
        let words = pictureWords(level).shuffled()
        return fresh(words, n, picture: \.emoji).map { w in
            let match = Bool.random()
            let other = words.shuffled().first {
                $0.id != w.id && !samePicture($0, w) && !usedPictures.contains(identity($0.emoji))
            } ?? w
            if !match { usedPictures.insert(identity(other.emoji)) }
            let pic = match ? w.emoji : other.emoji
            return ExamQuestion(
                section: .reading, part: "Word and picture", instruction: "Does the word match the picture?",
                picture: pic, text: w.hanzi, options: ExamQuestion.trueFalse, answer: match || samePicture(other, w) ? 0 : 1,
                itemID: w.id, transcript: [narrator(w.hanzi, w.pinyin)], english: "\(w.hanzi) means “\(w.english)”.")
        }
    }

    /// Read a sentence/dialogue; choose the picture.
    static func readSentencePicture(_ level: Int, _ n: Int) -> [ExamQuestion] {
        let items = ContentStore.listening(level: level, kinds: ["picture"], atLeast: n).shuffled()
        return fresh(items, n, picture: \.picture).compactMap { item in
            guard let correct = item.picture else { return nil }
            let (opts, ans) = pictureOptions(correct: correct, level: level, total: 4)
            return ExamQuestion(
                section: .reading, part: "Sentence and picture", instruction: "Read and choose the matching picture.",
                text: item.lines.map { $0.label + $0.text }.joined(separator: "\n"),
                options: opts, answer: ans, itemID: item.id, transcript: item.lines, english: item.english)
        }
    }

    private struct ReplyPair {
        let id: String
        let q: DialogueLine
        let a: DialogueLine
        let english: String
    }

    private static func replyPairs(_ level: Int) -> [ReplyPair] {
        ContentStore.reading(level: level, kinds: ["reply"]).compactMap { r in
            guard let reply = r.reply else { return nil }
            return ReplyPair(id: r.id, q: narrator(r.text, r.pinyin),
                             a: narrator(reply, r.replyPinyin ?? ""), english: r.english ?? "")
        }
    }

    /// Choose the best reply.
    static func readReply(_ level: Int, _ n: Int) -> [ExamQuestion] {
        var pairs = replyPairs(level)
        // Higher levels: build pairs from two-line dialogues of that level.
        if pairs.count < n + 3 {
            pairs += ContentStore.listening(level: level, kinds: ["dialogue", "picture"])
                .filter { $0.lines.count == 2 }
                .map { ReplyPair(id: $0.id, q: $0.lines[0], a: $0.lines[1], english: $0.english) }
        }
        if pairs.count < n + 3 && level > 1 { pairs += replyPairs(level - 1) }
        let shuffled = pairs.shuffled()
        return shuffled.prefix(n).map { p in
            let (opts, ans) = textOptions(correct: p.a.text, wrong: shuffled.map(\.a.text))
            return ExamQuestion(
                section: .reading, part: "Question and answer", instruction: "Choose the best reply.",
                text: p.q.text, options: opts, answer: ans, itemID: p.id,
                transcript: [p.q, p.a], english: p.english)
        }
    }

    /// Fill in the blank.
    static func readCloze(_ level: Int, _ n: Int) -> [ExamQuestion] {
        var items: [ExamQuestion] = ContentStore.reading(level: level, kinds: ["cloze"], atLeast: n).compactMap { c in
            guard let options = c.options, let answer = c.answer else { return nil }
            return ExamQuestion(
                section: .reading, part: "Fill in the blank", instruction: "Choose the word that fits the blank.",
                text: c.text, options: options.map { AnswerOption(text: $0) }, answer: answer, itemID: c.id,
                transcript: [narrator(c.text.replacingOccurrences(of: "＿＿", with: options[answer]), c.pinyin)],
                english: c.english ?? "")
        }
        // Grammar blanks of this level make extra variety.
        for p in GrammarStore.points(level: level) {
            for f in p.blanks {
                items.append(ExamQuestion(
                    section: .reading, part: "Fill in the blank", instruction: "Choose the word that fits the blank.",
                    text: f.sentence, options: f.options.map { AnswerOption(text: $0) },
                    answer: f.options.firstIndex(of: f.answer) ?? 0, itemID: p.id,
                    english: f.english, note: "Grammar: \(p.title). \(p.explanation)"))
            }
        }
        return Array(items.shuffled().prefix(n))
    }

    /// Read a passage; is the ★ statement true? (Listening statements double as reading texts.)
    static func readPassageTF(_ level: Int, _ n: Int) -> [ExamQuestion] {
        var items: [ExamQuestion] = ContentStore.reading(level: level, kinds: ["passageTrueFalse"]).compactMap { r in
            guard let star = r.statement, let isTrue = r.isTrue else { return nil }
            return ExamQuestion(
                section: .reading, part: "Read and judge ★", instruction: "Read the text. Is the ★ sentence true?",
                text: r.text, statement: star, options: ExamQuestion.trueFalse, answer: isTrue ? 0 : 1, itemID: r.id,
                transcript: [narrator(r.text, r.pinyin)], english: (r.english ?? "") + "\n★ " + (r.statementEnglish ?? ""))
        }
        if items.count < n {
            items += ContentStore.listening(level: level, kinds: ["statement"], atLeast: n).compactMap { l in
                guard let star = l.statement, let isTrue = l.isTrue else { return nil }
                return ExamQuestion(
                    section: .reading, part: "Read and judge ★", instruction: "Read the text. Is the ★ sentence true?",
                    text: l.lines.map(\.text).joined(), statement: star, options: ExamQuestion.trueFalse,
                    answer: isTrue ? 0 : 1, itemID: l.id, transcript: l.lines,
                    english: l.english + "\n★ " + (l.statementEnglish ?? ""))
            }
        }
        return Array(items.shuffled().prefix(n))
    }

    /// Read a passage and answer a question.
    static func readPassageQuestion(_ level: Int, _ n: Int) -> [ExamQuestion] {
        var items: [ExamQuestion] = ContentStore.reading(level: level, kinds: ["passageQuestion"]).compactMap { r in
            guard let q = r.question, let options = r.options, let answer = r.answer else { return nil }
            return ExamQuestion(
                section: .reading, part: "Read and answer", instruction: "Read the text and answer the question.",
                text: r.text + "\n\n问：" + q, options: options.map { AnswerOption(text: $0) }, answer: answer,
                itemID: r.id, transcript: [narrator(r.text, r.pinyin), narrator("问：" + q, r.questionPinyin ?? "")],
                english: (r.english ?? "") + "\nQ: " + (r.questionEnglish ?? ""))
        }
        if items.count < n {
            items += ContentStore.listening(level: level, kinds: ["passage", "dialogue"]).filter { $0.lines.count >= 3 || $0.kind == "passage" }
                .compactMap { l in
                    guard let q = l.question, let options = l.options, let answer = l.answer else { return nil }
                    return ExamQuestion(
                        section: .reading, part: "Read and answer", instruction: "Read the text and answer the question.",
                        text: l.lines.map { $0.label + $0.text }.joined(separator: "\n") + "\n\n问：" + q,
                        options: options.map { AnswerOption(text: $0) }, answer: answer, itemID: l.id,
                        transcript: l.lines, english: l.english + "\nQ: " + (l.questionEnglish ?? ""))
                }
        }
        return Array(items.shuffled().prefix(n))
    }
}
